// Typical short request with tight timeout
ctx, cancel := context.WithTimeout(parentCtx, 120*time.Millisecond)
defer cancel()
stream := client.StartStream(ctx)
// If caller cancels, we request a short grace window to let server finish in-flight tokens
_ = stream.CancelWithGrace(ctx, 25*time.Millisecond)

// Long-lived consumer pattern
stream := client.StartStream(ctx)
for {
  msg, err := stream.Recv()
  if err != nil {
    // caller can choose to CancelWithGrace when shutting down
    break
  }
  process(msg)
}
_ = stream.CloseImmediate()

// Resumable reader example (uses session token)
sessionID := "sess-abc123"
stream := client.ResumeStream(ctx, sessionID)
// on transient cancel, attempt to resume within Retry-After window
